import styled from 'styled-components'
import { cores } from '../../styles'

export const Card = styled.div<{ $isHome?: boolean }>`
  background-color: ${(props) =>
    props.$isHome ? cores.brancoSeco : cores.rosa};
  overflow: hidden;
  width: 100%;
  max-width: ${({ $isHome }) => ($isHome ? '472px' : '100%')};
  margin-bottom: 48px;
  display: flex;
  flex-direction: column;
  position: relative;
`

export const Imagem = styled.img<{ $isHome?: boolean }>`
  width: 100%;
  height: ${(props) => (props.$isHome ? '200px' : '167px')};
  object-fit: cover;
  padding: ${(props) => (props.$isHome ? '0px' : '8px')};
`
